package main

import (
	"math"
	"regexp"
	"strconv"
	"strings"
)

func AnalyzeLogsGo(args map[string]interface{}) map[string]interface{} {
	logLinesRaw := args["log_lines"]
	logLinesSlice := logLinesRaw.([]interface{})

	logLines := make([]string, len(logLinesSlice))
	for i, v := range logLinesSlice {
		logLines[i] = v.(string)
	}

	errorCount := 0
	warningCount := 0
	infoCount := 0
	var responseTimes []int

	re := regexp.MustCompile(`response_time=(\d+)ms`)

	for _, line := range logLines {
		lower := strings.ToLower(line)

		if strings.Contains(lower, "error") || strings.Contains(lower, "exception") {
			errorCount++
		} else if strings.Contains(lower, "warn") {
			warningCount++
		} else if strings.Contains(lower, "info") {
			infoCount++
		}

		matches := re.FindStringSubmatch(line)
		if len(matches) > 1 {
			if rt, err := strconv.Atoi(matches[1]); err == nil {
				responseTimes = append(responseTimes, rt)
			}
		}
	}

	avgRT := 0.0
	maxRT := 0
	if len(responseTimes) > 0 {
		sum := 0
		for _, rt := range responseTimes {
			sum += rt
			if rt > maxRT {
				maxRT = rt
			}
		}
		avgRT = float64(sum) / float64(len(responseTimes))
	}

	return map[string]interface{}{
		"total_lines":          len(logLines),
		"error_count":          errorCount,
		"warning_count":        warningCount,
		"info_count":           infoCount,
		"avg_response_time_ms": math.Round(avgRT*100) / 100,
		"slowest_request_ms":   maxRT,
	}
}
